import { Component, EventEmitter, Input, Output, OnInit, Optional, Inject, SimpleChanges, ChangeDetectorRef } from '@angular/core';
import { ContactFormComponent } from '../contact-form/contact-form.component';
import { MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { CommonModule } from '@angular/common';
import { IconComponent } from '../../icon/icon.component';
import { ButtonComponent } from '../../button/button.component';
import { AvatarComponent } from '../../avatar/avatar.component';
import { BadgeComponent } from '../../badge/badge.component';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { ContactService } from '../../../services/contact/contact.service';
import { MatMenuModule } from '@angular/material/menu';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';

@Component({
  selector: 'app-contactdetail',
  standalone: true,
  imports: [CommonModule, IconComponent, ButtonComponent, AvatarComponent, BadgeComponent, MatMenuModule],
  templateUrl: './contactdetail.component.html',
  styleUrl: './contactdetail.component.scss'
})
export class ContactdetailComponent implements OnInit {
  @Input() detail: any;
  @Input() onlydetail: boolean = false;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() nContactid: string;
  @Input() nCaseid: string;
  @Input() canEdit: boolean;
  @Input() canDelete: boolean;

  constructor(
    @Optional() private dialogRef: MatDialogRef<ContactFormComponent>,
    @Optional() @Inject(MAT_DIALOG_DATA) private dialogData: any,
    private contactService: ContactService,
    private cdr: ChangeDetectorRef,
    private cf: CommonfunctionService
  ) {
    // If dialog data is provided, use it
    if (this.dialogData) {
      this.detail = this.dialogData.detail;

      this.onlydetail = this.dialogData.onlydetail || false;
      this.nContactid = this.dialogData.nContactid;
    }
  }


  ngOnInit(): void {

    console.log('ngOnInit - detail:', this.detail);
    console.log('ngOnInit - onlydetail:', this.onlydetail);
    this.initializeData();
  }

  ngOnChanges(changes: SimpleChanges): void {
    console.log('ngOnChanges - changes:', changes);
    if (changes['detail']) {
      console.log('detail changed:', this.detail);
      this.initializeData();
    }
  }

  private initializeData(): void {

    if (this.detail) {
      this.nContactid = this.detail.nContactid;
      // Initialize other properties as needed
    }
    else if (this.nContactid) {
      this.getContactDetail();
    }

  }



  getContactDetail() {

    // Implement your logic to fetch contact details
    // For example:
    this.contactService.getContactDetail(this.nContactid).then((res) => {
      this.detail = res;
      this.cdr.detectChanges();
    });
  }

  edit() {
    this.OnEvent.emit({ event: 'EDIT', data: { nContactid: this.nContactid } });
    if (this.dialogRef) {
      this.dialogRef.close('EDIT');
    }
  }

  viewfacts() {
    // Implement viewfacts logic
    if (!this.nCaseid) return;
    this.cf.goto('myfiles/workspace', { id: this.nCaseid, tab: 'C' });
  }

  close() {
    if (this.dialogRef) {
      this.dialogRef.close();
    }
  }

  deleteContact() {
    this.OnEvent.emit({ event: 'DELETE', data: { nContactid: this.nContactid } });
    if (this.dialogRef) {
      this.dialogRef.close('DELETE');
    }
  }
}